package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time so tests can control elapsed time.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Bucket is a concurrency-safe token bucket.
type Bucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// New creates a Bucket allowing rate tokens/second up to capacity.
func New(capacity int, rate float64, clock Clock) (*Bucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	return &Bucket{
		capacity: float64(capacity),
		tokens:   float64(capacity),
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// NewReal returns a Bucket using the system clock.
func NewReal(capacity int, rate float64) (*Bucket, error) {
	return New(capacity, rate, realClock{})
}

// AllowN reports whether n tokens can be consumed, consuming them if so.
func (b *Bucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	if n == 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token can be consumed.
func (b *Bucket) Allow() bool { return b.AllowN(1) }

// Tokens returns the current estimated available tokens.
func (b *Bucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	return b.tokens
}

func (b *Bucket) refillLocked() {
	now := b.clock.Now()
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}
