// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is injectable for deterministic tests.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token bucket.
type Limiter struct {
	mu      sync.Mutex
	clock   Clock
	capacity float64
	rate    float64 // tokens per second
	tokens  float64
	last    time.Time
}

// New validates configuration and returns a full bucket.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be > 0")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		clock:   clock,
		capacity: float64(capacity),
		rate:    rate,
		tokens:  float64(capacity),
		last:    now,
	}, nil
}

func (l *Limiter) refillLocked(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed * l.rate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = now
}

// AllowN reports whether n tokens are available and consumes them if so.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refillLocked(l.clock.Now())
	if float64(n) > l.capacity || l.tokens < float64(n) {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether one token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current approximate available tokens.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refillLocked(l.clock.Now())
	return l.tokens
}
