				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
		})
	}
}

func TestAllowNSequence(t *testing.T) {
	fc := newFakeClock()
	l, err := New(5, 1, fc)
	if err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name    string
		advance time.Duration
		n       int
		want    bool
	}{
		{"consume 3", 0, 3, true},
		{"too many", 0, 3, false},
		{"refill 2s", 2 * time.Second, 4, true},
		{"empty", 0, 1, false},
		{"refill 1s", time.Second, 5, true},
